import type { Storage } from "@google-cloud/storage";

/** Private file storage. Object keys are generated by the server. */
export interface BlobStore {
  readonly bucket: string;
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  /** Succeeds if the object is already gone. */
  delete(key: string): Promise<void>;
}

export function gcsBlobStore(storage: Storage, bucket: string): BlobStore {
  const file = (key: string) => storage.bucket(bucket).file(key);
  return {
    bucket,
    async put(key, bytes, contentType) {
      await file(key).save(Buffer.from(bytes), {
        contentType,
        resumable: false,
        preconditionOpts: { ifGenerationMatch: 0 },
      });
    },
    async get(key) {
      const [contents] = await file(key).download();
      return contents;
    },
    async delete(key) {
      await file(key).delete({ ignoreNotFound: true });
    },
  };
}
